package io.knowledgebrain.learning;
import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class EvidenceSessionStoreIntegrationTest extends EvidenceSessionFixtures {
 @BeforeEach void setup(){init();}
 void status(int expected,Runnable run){assertEquals(expected,assertThrows(ResponseStatusException.class,run::run).getStatusCode().value());}
 @Test void defaultReadAndEmptyUnlinkDoNotWriteForAnyVariant(){for(String kind:List.of("NOTE","CONCEPT","MEDIA")){var id=evidence(kind);int count=sql.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);var zero=links.get(space,roadmap,id,kind);assertNull(zero.linkId());assertEquals(0,zero.version());assertEquals("UNLINKED",zero.state());assertEquals(zero,links.change(space,roadmap,id,kind,actor,0,new EvidenceSessionStore.Input(null,null),trace));assertTrue(links.history(space,roadmap,id,kind,Long.MAX_VALUE,5).isEmpty());assertEquals(count,sql.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));}}
 @Test void allKindsPinSessionsIndependentlyAndNeverRewriteEvidenceTimeOrProgress(){var session=session(node);var root=roadmaps.get(space,roadmap);var summary=study.summary(space,roadmap);var retained=sql.queryForList("SELECT snapshot::text FROM learning_evidence_revision WHERE evidence_id IN (SELECT evidence_id FROM learning_evidence WHERE roadmap_id=?)",roadmap);for(String kind:List.of("NOTE","CONCEPT","MEDIA")){var id=evidence(kind);var original=sql.queryForObject("SELECT snapshot::text FROM learning_evidence_revision WHERE evidence_id=?",String.class,id);var link=link(id,kind,session,0);assertEquals(7,link.linkId().version());assertEquals("PRIVATE",link.visibility());assertEquals(session.startedAt(),link.startedAt());assertEquals(session.durationSeconds(),link.durationSeconds());assertEquals(link,link(id,kind,session,1));status(412,()->link(id,kind,session,0));assertEquals(1,events(link.linkId()));assertEquals(original,sql.queryForObject("SELECT snapshot::text FROM learning_evidence_revision WHERE evidence_id=?",String.class,id));var unlinked=links.change(space,roadmap,id,kind,actor,1,new EvidenceSessionStore.Input(null,null),trace);assertEquals(link.linkId(),unlinked.linkId());assertEquals(2,unlinked.version());assertNull(unlinked.sessionId());assertEquals(link,links.history(space,roadmap,id,kind,2,5).getFirst().snapshot());}assertEquals(root,roadmaps.get(space,roadmap));assertEquals(session,study.session(space,roadmap,session.sessionId()));assertEquals(summary,study.summary(space,roadmap));}
 @Test void currentVersionAndSameNodeAreRequiredWhileOldPinsSurviveEditsAndRetirement(){var id=evidence("NOTE");var s=session(node);var first=link(id,"NOTE",s,0);var updated=study.changeSession(space,roadmap,s.sessionId(),actor,1,new LearningStudyStore.Input(node,s.startedAt(),s.endedAt(),"Changed memo"),false,trace);assertEquals(first,links.get(space,roadmap,id,"NOTE"));status(409,()->link(evidence("NOTE"),"NOTE",s,0));var refreshed=link(id,"NOTE",updated,1);assertEquals(2L,refreshed.sessionVersion());study.changeSession(space,roadmap,s.sessionId(),actor,2,null,true,trace);assertEquals(refreshed,links.get(space,roadmap,id,"NOTE"));status(404,()->link(evidence("NOTE"),"NOTE",updated,0));assertEquals(refreshed,link(id,"NOTE",updated,2));status(409,()->link(evidence("NOTE"),"NOTE",session(otherNode),0));}
 @Test void scopesTypedIdsMalformedInputAndStaleVersionsNeverPartiallyWrite(){var id=evidence("CONCEPT");var s=session(node);status(404,()->links.get(actor,roadmap,id,"CONCEPT"));status(404,()->links.get(space,ids.next(),id,"CONCEPT"));status(404,()->links.get(space,roadmap,id,"NOTE"));status(404,()->links.change(space,roadmap,id,"CONCEPT",actor,0,new EvidenceSessionStore.Input(ids.next(),1L),trace));status(400,()->links.change(space,roadmap,id,"CONCEPT",actor,0,new EvidenceSessionStore.Input(null,1L),trace));status(400,()->links.change(space,roadmap,id,"CONCEPT",actor,0,new EvidenceSessionStore.Input(s.sessionId(),0L),trace));status(412,()->link(id,"CONCEPT",s,1));assertEquals(0,links.get(space,roadmap,id,"CONCEPT").version());}
 @Test void concurrentFirstWritersShareRootLockAndOnlyOneRevisionCommits()throws Exception{var id=evidence("MEDIA");var s=session(node);try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);var results=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++)results.add(pool.submit(()->{gate.await();try{link(id,"MEDIA",s,0);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));assertEquals(Set.of(200,412),Set.of(results.get(0).get(),results.get(1).get()));var value=links.get(space,roadmap,id,"MEDIA");assertEquals(1,value.version());assertEquals(1,events(value.linkId()));assertEquals(1,links.history(space,roadmap,id,"MEDIA",Long.MAX_VALUE,10).size());}}
 @Test void archivedEvidenceNodeAndSessionPermitUnlinkAndKnownHistoryButNoNewLink(){var id=evidence("NOTE");var s=session(node);var one=link(id,"NOTE",s,0);new LearningEvidenceStore(ds,clock,roadmaps).change(space,roadmap,id,actor,1,null,true,trace);roadmaps.graph(space,roadmap,actor,2,new RoadmapGraph.Edit(List.of(),List.of()),trace);study.changeSession(space,roadmap,s.sessionId(),actor,1,null,true,trace);assertEquals(one,links.get(space,roadmap,id,"NOTE"));var unlinked=links.change(space,roadmap,id,"NOTE",actor,1,new EvidenceSessionStore.Input(null,null),trace);status(404,()->link(id,"NOTE",s,2));roadmaps.metadata(space,roadmap,actor,3,null,null,true,trace);assertEquals(unlinked,links.get(space,roadmap,id,"NOTE"));assertEquals(one,links.history(space,roadmap,id,"NOTE",2,5).getFirst().snapshot());status(404,()->links.change(space,roadmap,id,"NOTE",actor,2,new EvidenceSessionStore.Input(null,null),trace));}
 @Test void linkHistoryUsesBoundedDescendingVersionCursorAndStableLinkId(){var id=evidence("NOTE");var s=session(node);var first=link(id,"NOTE",s,0);for(int v=1;v<8;v++)links.change(space,roadmap,id,"NOTE",actor,v,v%2==1?new EvidenceSessionStore.Input(null,null):new EvidenceSessionStore.Input(s.sessionId(),1L),trace);assertEquals(first.linkId(),links.get(space,roadmap,id,"NOTE").linkId());assertEquals(List.of(8L,7L,6L,5L,4L),links.history(space,roadmap,id,"NOTE",Long.MAX_VALUE,5).stream().map(EvidenceSessionStore.Revision::version).toList());assertEquals(List.of(3L,2L,1L),links.history(space,roadmap,id,"NOTE",4,5).stream().map(EvidenceSessionStore.Revision::version).toList());status(400,()->links.history(space,roadmap,id,"NOTE",0,5));status(400,()->links.history(space,roadmap,id,"NOTE",Long.MAX_VALUE,11));assertEquals(8,events(first.linkId()));}
}
